function apiOrigin() {
  if (process.env.NEXT_PUBLIC_SITE_URL) {
    return process.env.NEXT_PUBLIC_SITE_URL.replace(/\/$/, '')
  }
  if (process.env.VERCEL_URL) {
    return `https://${process.env.VERCEL_URL}`
  }
  return `http://127.0.0.1:${process.env.PORT ?? '3000'}`
}

type Analytics = {
  views: number
  uniqueVisitors: number
  period: string
}

type Notifications = {
  items: Array<{ id: string; message: string; read: boolean }>
}

type Settings = {
  theme: string
  emailDigest: string
  notificationsEnabled: boolean
}

async function getDashboardData() {
  const base = apiOrigin()

  try {
    const [analytics, notifications, settings] = await Promise.all([
      fetch(`${base}/api/analytics`).then((r) => r.json()),
      fetch(`${base}/api/notifications`).then((r) => r.json()),
      fetch(`${base}/api/settings`).then((r) => r.json()),
    ])

    return {
      analytics: analytics as Analytics,
      notifications: notifications as Notifications,
      settings: settings as Settings,
    }
  } catch {
    return {
      analytics: {
        views: 0,
        uniqueVisitors: 0,
        period: 'last 7 days',
      },
      notifications: {
        items: [],
      },
      settings: {
        theme: 'system',
        emailDigest: 'weekly',
        notificationsEnabled: false,
      },
    }
  }
}

export default async function Dashboard() {
  const { analytics, notifications, settings } = await getDashboardData()

  const unreadCount = notifications.items.filter((n) => !n.read).length

  return (
    <div>
      <h2>Dashboard Content</h2>

      <section aria-labelledby="analytics-heading">
        <h3 id="analytics-heading">Analytics</h3>
        <p>
          {analytics.views.toLocaleString()} views ·{' '}
          {analytics.uniqueVisitors.toLocaleString()} unique visitors (
          {analytics.period})
        </p>
      </section>

      <section aria-labelledby="notifications-heading">
        <h3 id="notifications-heading">
          Notifications
          {unreadCount > 0 ? ` (${unreadCount} unread)` : null}
        </h3>
        {notifications.items.length === 0 ? (
          <p>No notifications.</p>
        ) : (
          <ul>
            {notifications.items.map((n) => (
              <li key={n.id}>
                {n.read ? '' : <strong>[New] </strong>}
                {n.message}
              </li>
            ))}
          </ul>
        )}
      </section>

      <section aria-labelledby="settings-heading">
        <h3 id="settings-heading">Settings</h3>
        <ul>
          <li>Theme: {settings.theme}</li>
          <li>Email digest: {settings.emailDigest}</li>
          <li>
            Push notifications:{' '}
            {settings.notificationsEnabled ? 'On' : 'Off'}
          </li>
        </ul>
      </section>
    </div>
  )
}

